        i: [['c-p-deal', 'Онлайн: панель домовленості в Дона — жести й набрана послідовність'], ['c-p-dealwatch', 'Мафія бачить жести Дона великими'], ['c-night0', 'Так це бачить ведучий: сім’я, хвилина, жести']],
